def compute(vars):
    start_balance = vars["v1"]
    end_balance = vars["v2"]
    change = end_balance - start_balance
    value = change / 1000000

    return {
        "value": value,
        "trace": {
            "start_balance": start_balance,
            "end_balance": end_balance,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
